// Preconditions: jpg must be a valid guetzli::JPEGData instance initialized by
// some initializer (we enforce via attribute tracking). The method is const and
// should not mutate state; we keep jpg alive by returning it as an output.
if (FUZZ_GET_ATTR_INT(jpg, "jpegdata_init") != 1) { FUZZ_BAIL(); }
const guetzli::JPEGData* cjpg = static_cast<const guetzli::JPEGData*>(jpg);
bool is420 = cjpg->Is420();
// If we know from prior initialization that sampling is 4:4:4, then Is420 must be false.
const char* sampling = FUZZ_GET_ATTR_STR(jpg, "sampling");
if (sampling && sampling[0] != '\0') {
  int is_444 = (std::string(sampling) == std::string("444"));
  if (is_444) { FUZZ_ASSERT(!is420, "JPEGData::Is420() must be false for 4:4:4 sampling"); }
}
// Persist the object by listing it as an output.

// Preconditions: jpg must be a valid, initialized guetzli::JPEGData.
if (FUZZ_GET_ATTR_INT(jpg, "jpegdata_init") != 1) { FUZZ_BAIL(); }
const guetzli::JPEGData* cjpg = static_cast<const guetzli::JPEGData*>(jpg);
bool is444 = cjpg->Is444();
// If we know sampling was initialized as 4:4:4, ensure API reports true.
const char* sampling = FUZZ_GET_ATTR_STR(jpg, "sampling");
if (sampling && sampling[0] != '\0') {
  int is_444_attr = (std::string(sampling) == std::string("444"));
  if (is_444_attr) { FUZZ_ASSERT(is444, "JPEGData::Is444() must be true for 4:4:4 sampling"); }
}
// Keep jpg alive by returning it as an output.

// Generate positive, bounded dimensions to avoid pathological allocations.
int w = (int)(*FUZZ_PARAM(unsigned int) % 2048u) + 1;
int h = (int)(*FUZZ_PARAM(unsigned int) % 2048u) + 1;
// Create a fresh JPEGData instance and initialize for YUV444.
guetzli::JPEGData* jpg = new guetzli::JPEGData();
guetzli::InitJPEGDataForYUV444(w, h, jpg);
// Track initialization and sampling so downstream stubs can enforce invariants.
FUZZ_SET_ATTR_INT(jpg, "jpegdata_init", 1);
FUZZ_SET_ATTR_STR(jpg, "sampling", "444");
FUZZ_SET_ATTR_INT(jpg, "width", w);
FUZZ_SET_ATTR_INT(jpg, "height", h);
// Return the persistent object to the pool as an output.

// Preconditions: jpg must be an initialized guetzli::JPEGData pointer.
if (FUZZ_GET_ATTR_INT(jpg, "jpegdata_init") != 1) { FUZZ_BAIL(); }
guetzli::JPEGData* j = static_cast<guetzli::JPEGData*>(jpg);
// Prepare three 8x8 tables. Use FUZZ_PARAM on fixed-size arrays and constrain values.
const int (*t0)[64] = FUZZ_PARAM(int[64]);
const int (*t1)[64] = FUZZ_PARAM(int[64]);
const int (*t2)[64] = FUZZ_PARAM(int[64]);
int q[3][64];
for (int i = 0; i < 64; ++i) {
  // Constrain to typical positive ranges (1..2048) to avoid zeros or negatives.
  q[0][i] = (std::abs((*t0)[i]) % 2048) + 1;
  q[1][i] = (std::abs((*t1)[i]) % 2048) + 1;
  q[2][i] = (std::abs((*t2)[i]) % 2048) + 1;
}
// Save the quantization tables into the JPEGData.
guetzli::SaveQuantTables(q, j);
// Keep jpg alive by returning it as an output.

// Preconditions enforced via attributes: ensure this opaque pointer is a guetzli::JPEGData instance.
// The fuzzer runtime supplies a non-null jpg pointer; we validate it represents the right type.
const char* type_tag = FUZZ_GET_ATTR_STR(jpg, "type");
int is_jpegdata = (type_tag && type_tag[0] != '\0' && std::string(type_tag) == "guetzli::JPEGData");
if (!is_jpegdata) { FUZZ_BAIL(); }

// Cast the validated opaque pointer to the expected API type and call the target.
// We assume the underlying object is valid and owned by the pool/runtime.
guetzli::JPEGData* jd = static_cast<guetzli::JPEGData*>(jpg);

// Call under test: adds a JFIF APP0 segment to the JPEGData.
guetzli::AddApp0Data(jd);

// Track that APP0 has been (attempted to be) added to this JPEGData for downstream stubs.
FUZZ_SET_ATTR_INT(jpg, "has_app0", 1);

// jpg remains alive and is returned to the pool as an output.
// Validation summary: input type tag ensures correct object kind; function has no return value,
// so we record state via attributes and keep the object persistent.

// Create a fresh JPEGData to receive the encoding result.
guetzli::JPEGData* jd = new guetzli::JPEGData();
void* jpg = static_cast<void*>(jd);
// Tag this opaque pointer so future stubs can verify correct type and provenance.
FUZZ_SET_ATTR_STR(jpg, "type", "guetzli::JPEGData");
FUZZ_SET_ATTR_INT(jpg, "has_app0", 0);

// Generate a random RGB buffer. Keep dimensions small and consistent with buffer size.
std::string buf = FUZZ_PARAM_STR();
size_t max_pixels = buf.size() / 3u; // each pixel needs 3 bytes
if (max_pixels == 0) { FUZZ_BAIL(); }

// Choose width in [1, min(256, max_pixels)]
unsigned int w_choice = *FUZZ_PARAM(unsigned int);
int w = static_cast<int>(w_choice % (int)std::min<size_t>(256, max_pixels)) + 1;
size_t max_h = max_pixels / static_cast<size_t>(w);
if (max_h == 0) { FUZZ_BAIL(); }
// Choose height in [1, min(256, max_h)]
unsigned int h_choice = *FUZZ_PARAM(unsigned int);
int h = static_cast<int>(h_choice % (int)std::min<size_t>(256, max_h)) + 1;

// Truncate/reshape the buffer to exactly w*h*3 bytes.
size_t need = static_cast<size_t>(w) * static_cast<size_t>(h) * 3u;
std::vector<uint8_t> rgb;
rgb.reserve(need);
rgb.insert(rgb.end(), reinterpret_cast<const uint8_t*>(buf.data()), reinterpret_cast<const uint8_t*>(buf.data()) + need);

// Perform encoding. The function returns false on failure; honor that by bailing.
bool ok = guetzli::EncodeRGBToJpeg(rgb, w, h, jd);
if (!ok) { FUZZ_BAIL(); }

// Mark that this JPEGData now contains encoded content.
FUZZ_SET_ATTR_INT(jpg, "encoded", 1);

// Output: return the JPEGData object to the pool for further transformations (e.g., AddApp0Data).
// Validation summary: we constrain buffer size to exactly w*h*3, enforce positive dims, and bail on encode failure.

// Enforce: must be called before any CompareBlock() and not already in a block-comparison phase.
// Track phase with an attribute on the comparator object: 0 = idle, 1 = in block phase.
int phase = FUZZ_GET_ATTR_INT(comparator, "block_phase");
if (phase != 0) { FUZZ_BAIL(); }
comparator->StartBlockComparisons();
FUZZ_SET_ATTR_INT(comparator, "block_phase", 1);
// Keep comparator alive by returning it as an output.

// Enforce: Finish must follow a prior Start and end the block-comparison phase.
int phase = FUZZ_GET_ATTR_INT(comparator, "block_phase");
if (phase != 1) { FUZZ_BAIL(); }
comparator->FinishBlockComparisons();
FUZZ_SET_ATTR_INT(comparator, "block_phase", 0);
// Keep comparator alive by returning it as an output.

// Enforce: must be within a block-comparison phase started by StartBlockComparisons().
int phase = FUZZ_GET_ATTR_INT(comparator, "block_phase");
if (phase != 1) { FUZZ_BAIL(); }
// Choose small, non-negative macro-block coordinates and reasonable factors.
int block_x = (int)(*FUZZ_PARAM(unsigned int) % 256);
int block_y = (int)(*FUZZ_PARAM(unsigned int) % 256);
int factor_x = (int)(*FUZZ_PARAM(unsigned int) % 4) + 1; // [1,4]
int factor_y = (int)(*FUZZ_PARAM(unsigned int) % 4) + 1; // [1,4]
comparator->SwitchBlock(block_x, block_y, factor_x, factor_y);
// Record last block settings for potential downstream validation.
FUZZ_SET_ATTR_INT(comparator, "cur_block_x", block_x);
FUZZ_SET_ATTR_INT(comparator, "cur_block_y", block_y);
FUZZ_SET_ATTR_INT(comparator, "cur_factor_x", factor_x);
FUZZ_SET_ATTR_INT(comparator, "cur_factor_y", factor_y);
// Keep comparator alive by returning it as an output.

// Enforce: size should be non-negative; pick a bounded non-negative value.
int size = (int)(*FUZZ_PARAM(unsigned int) % 1000000u); // up to ~1MB
// Compute score relative to last Compare() (or baseline if none).
volatile double s = comparator->ScoreOutputSize(size);
(void)s; // touch to avoid optimizing away
// Keep comparator alive by returning it as an output.

// target_mul semantics: 1.0 default, <1 stricter, >1 looser. Choose in [0.1, 3.0].
double rnd = (double)(*FUZZ_PARAM(unsigned int) % 10000) / 10000.0; // [0,1)
double target_mul = 0.1 + rnd * (3.0 - 0.1);
volatile bool ok = comparator->DistanceOK(target_mul);
(void)ok;
// Keep comparator alive by returning it as an output.

// Retrieve the distance map (refers to last Compare() or baseline if none).
const std::vector<float> dm = comparator->distmap();
// Lightly exercise the result to encourage materialization.
size_t n = dm.size();
volatile float acc = 0.0f;
for (size_t i = 0; i < (n < 64 ? n : 64); ++i) { acc += dm[i] * 0.0f; }
(void)acc;
// Keep comparator alive by returning it as an output.

// Aggregate distance/similarity of last Compare() (or baseline if none).
volatile float agg = comparator->distmap_aggregate();
(void)agg;
// Keep comparator alive by returning it as an output.

// Query heuristic cutoff on block errors.
volatile float lim = comparator->BlockErrorLimit();
(void)lim;
// Keep comparator alive by returning it as an output.

// Enforce: direction must be +1 (up) or -1 (down).
int direction = ((*FUZZ_PARAM(unsigned int) % 2) == 0) ? 1 : -1;
// Choose small parameters to keep runtime fast and within reasonable bounds.
int max_block_dist = (int)(*FUZZ_PARAM(unsigned int) % 1024);
int factor_x = (int)(*FUZZ_PARAM(unsigned int) % 4) + 1; // [1,4]
int factor_y = (int)(*FUZZ_PARAM(unsigned int) % 4) + 1; // [1,4]
// target_mul in [0.25, 4.0]
double rnd = (double)(*FUZZ_PARAM(unsigned int) % 10000) / 10000.0; // [0,1)
double target_mul = 0.25 + rnd * (4.0 - 0.25);
// Prepare a synthetic distmap. Size/layout is implementation-specific; use a modest size.
size_t w = 32, h = 32; // 1024 elements
std::vector<float> distmap;
distmap.resize(w * h);
for (size_t i = 0; i < distmap.size(); ++i) {
  distmap[i] = (float)((*FUZZ_PARAM(unsigned int) % 1000) / 1000.0); // [0,1)
}
// Prepare output buffer; must be non-null.
std::vector<float> block_weight;
comparator->ComputeBlockErrorAdjustmentWeights(direction, max_block_dist, target_mul,
                                               factor_x, factor_y, distmap, &block_weight);
// Lightly touch the output to ensure it is realized.
volatile size_t bw_size = block_weight.size();
(void)bw_size;
// Keep comparator alive by returning it as an output.

// Preconditions:
// - params and stats are provided by the fuzzer runtime and are non-null.
// - out_data must be a valid non-null pointer; we provide a local std::string.
// - in_data should be a JPEG bitstream; we provide fuzz data and sometimes
//   inject a JPEG SOI to exercise success paths.

// Prepare input data (bounded size for performance)
std::string in = FUZZ_PARAM_STR();
if (in.size() > 2048) in.resize(2048);

// Occasionally coerce input to look like a JPEG by ensuring SOI marker at start
unsigned int tweak = *FUZZ_PARAM(unsigned int);
if ((tweak & 1u) != 0u) {
  if (in.size() < 2) in.resize(2, '\0');
  in[0] = static_cast<char>(0xFF);
  in[1] = static_cast<char>(0xD8);
}

// Optionally set a filename in stats for more code coverage where the API logs/uses it
// Safe to modify since it's owned by the struct (std::string value).
stats->filename = FUZZ_PARAM_FILENAME();

// out_data must be non-null
std::string out;

// Invoke target function
bool ok = guetzli::Process(*params, stats, in, &out);

// Enforce API contract: if ok, out should contain an encoded JPEG
if (!ok) {
  // Allowed API failure (e.g., invalid input); signal the fuzzer to try another path
  FUZZ_BAIL();
}
FUZZ_ASSERT(!out.empty(), "guetzli::Process returned true but produced empty output");

// Persist inputs by listing them as outputs (no deallocation here).

// Construct a Params object with fuzz-derived but bounded values to keep the API sane.
guetzli::Params* params = new guetzli::Params();
// butteraugli_target: choose in [0.1, 10.0]
{
  double r = (double)(*FUZZ_PARAM(unsigned int) % 10001) / 1000.0; // [0,10.001]
  if (r < 0.1) r = 0.1;
  if (r > 10.0) r = 10.0;
  params->butteraugli_target = static_cast<float>(r);
}
// Booleans
params->clear_metadata = ((*FUZZ_PARAM(unsigned int) & 1u) != 0u);
params->try_420 = ((*FUZZ_PARAM(unsigned int) & 1u) != 0u);
params->force_420 = ((*FUZZ_PARAM(unsigned int) & 1u) != 0u);
params->use_silver_screen = ((*FUZZ_PARAM(unsigned int) & 1u) != 0u);
// zeroing_greedy_lookahead: pick small non-negative integer [0, 16]
params->zeroing_greedy_lookahead = (int)(*FUZZ_PARAM(unsigned int) % 17u);
// new_zeroing_model
params->new_zeroing_model = ((*FUZZ_PARAM(unsigned int) & 1u) != 0u);

// Tag with attributes for downstream stubs if needed.
FUZZ_SET_ATTR_INT(params, "params_init", 1);
// Validation: constructed object is heap-allocated and fields are set within reasonable ranges.

// Allocate a new ProcessStats and initialize optional fields safely.
guetzli::ProcessStats* stats = new guetzli::ProcessStats();

// Populate counters with a few entries for coverage; keep sizes small.
int n = (int)(*FUZZ_PARAM(unsigned int) % 4u); // up to 3 entries
for (int i = 0; i < n; ++i) {
  std::string key = FUZZ_PARAM_STR();
  if (key.size() > 32) key.resize(32);
  int val = (int)(*FUZZ_PARAM(unsigned int) % 1000u);
  stats->counters[key] = val;
}

// Optionally provide a filename; safe as it's an owned std::string.
stats->filename = FUZZ_PARAM_FILENAME();

// Optionally provide a debug_output buffer to exercise code paths that write to it.
if ((*FUZZ_PARAM(unsigned int) & 1u) != 0u) {
  std::string* dbg = new std::string();
  // Seed with some fuzz text, bounded.
  std::string seed = FUZZ_PARAM_STR();
  if (seed.size() > 128) seed.resize(128);
  *dbg = seed;
  stats->debug_output = dbg; // lifetime managed externally; we keep it allocated for the fuzz run.
}

// Do not set debug_output_file to avoid I/O side effects.

FUZZ_SET_ATTR_INT(stats, "stats_init", 1);
// Validation: stats is non-null, owns its strings, and optional pointers are either null or valid heap objects.

// Concrete, self-contained Comparator implementation for fuzzing without using FUZZ_PARAM inside methods.
// All randomness is seeded outside and stored in the object; methods are deterministic based on that state.
class FuzzComparator : public guetzli::Comparator {
 public:
  FuzzComparator(int w, int h, uint32_t seed)
      : width_(w), height_(h), in_block_phase_(false), last_size_(0), seed_(seed) {
    if (width_ <= 0) width_ = 1;
    if (height_ <= 0) height_ = 1;
    distmap_.assign((size_t)width_ * (size_t)height_, 0.0f);
    // Initialize a pseudo-random distance map using an internal LCG.
    for (size_t i = 0; i < distmap_.size(); ++i) {
      distmap_[i] = randUnit_();
    }
  }
  virtual ~FuzzComparator() {}

  void Compare(const guetzli::OutputImage& /*img*/) override {
    // Update distmap_ deterministically based on current seed_ to simulate a comparison.
    for (size_t i = 0; i < distmap_.size(); ++i) {
      // Blend old value with a new pseudo-random value to change but keep bounded in [0,1].
      float r = randUnit_();
      distmap_[i] = 0.6f * distmap_[i] + 0.4f * r;
    }
    // Track that a comparison happened via last_size_ sentinel (uses RNG but no FUZZ_PARAM).
    last_size_ = (int)(rand32_() % 100000u);
  }

  void StartBlockComparisons() override { in_block_phase_ = true; }
  void FinishBlockComparisons() override { in_block_phase_ = false; }

  void SwitchBlock(int block_x, int block_y, int factor_x, int factor_y) override {
    // Record the last block context; no validation here (the harness enforces sequencing via attributes).
    last_block_x_ = block_x;
    last_block_y_ = block_y;
    last_factor_x_ = factor_x;
    last_factor_y_ = factor_y;
  }

  double CompareBlock(const guetzli::OutputImage& /*img*/, int off_x, int off_y) const override {
    // Deterministic per-block value derived from offsets and stored state.
    // Keep within a reasonable range.
    uint32_t h = (uint32_t)(off_x * 1315423911u) ^ (uint32_t)(off_y * 2654435761u) ^ seed_ ^ (uint32_t)(width_ * 17 + height_ * 31);
    double v = (double)((h & 0x3FFu)) / 64.0; // [0, ~15.98]
    // If not in a block phase, still return a value; harness ensures phase correctness externally.
    (void)in_block_phase_;
    return v;
  }

  double ScoreOutputSize(int size) const override {
    if (size < 0) size = 0;
    double agg = (double)distmap_aggregate();
    return agg - (double)size * 0.0001; // simple heuristic
  }

  bool DistanceOK(double target_mul) const override {
    if (target_mul <= 0.0) target_mul = 1.0; // avoid degenerate scaling
    double agg = (double)distmap_aggregate();
    double limit = (double)BlockErrorLimit() * target_mul;
    return agg <= limit;
  }

  const std::vector<float> distmap() const override { return distmap_; }

  float distmap_aggregate() const override {
    float s = 0.0f;
    const size_t n = distmap_.size();
    for (size_t i = 0; i < n; ++i) s += distmap_[i];
    return (n == 0) ? 0.0f : s / (float)n;
  }

  float BlockErrorLimit() const override {
    // Slightly dependent on dimensions to introduce variety.
    return 1.5f + (float)((width_ + height_) % 13) * 0.01f;
  }

  void ComputeBlockErrorAdjustmentWeights(int direction, int max_block_dist, double target_mul,
                                          int factor_x, int factor_y, const std::vector<float>& distmap,
                                          std::vector<float>* block_weight) override {
    if (!block_weight) return;
    if (direction != 1 && direction != -1) direction = 1;
    if (max_block_dist < 0) max_block_dist = 0;
    if (factor_x <= 0) factor_x = 1;
    if (factor_y <= 0) factor_y = 1;
    if (target_mul <= 0.0) target_mul = 1.0;

    block_weight->resize(distmap.size());
    // Simple transformation: scale by target_mul and modulate by direction and factors.
    const float dir = (direction > 0) ? 1.0f : 0.9f;
    const float fx = 1.0f + 0.05f * (float)(factor_x % 5);
    const float fy = 1.0f + 0.05f * (float)(factor_y % 5);
    const float cap = (max_block_dist > 0) ? (float)max_block_dist : 1e9f;
    for (size_t i = 0; i < distmap.size(); ++i) {
      float w = (float)(distmap[i] * (float)target_mul * dir * fx * fy);
      if (w > cap) w = cap;
      (*block_weight)[i] = w;
    }
  }

 private:
  // Simple LCG for deterministic pseudo-randomness within the object.
  uint32_t rand32_() const { seed_ = seed_ * 1664525u + 1013904223u; return seed_; }
  float randUnit_() const { return (float)((rand32_() >> 8) & 0xFFFFu) / 65535.0f; }

  int width_;
  int height_;
  bool in_block_phase_;
  int last_size_;
  mutable uint32_t seed_;
  int last_block_x_ = 0, last_block_y_ = 0, last_factor_x_ = 1, last_factor_y_ = 1;
  std::vector<float> distmap_;
};

// Choose modest dimensions for the synthetic baseline image and a seed from fuzz input.
int w = (int)(*FUZZ_PARAM(unsigned int) % 64u) + 1;
int h = (int)(*FUZZ_PARAM(unsigned int) % 64u) + 1;
uint32_t seed = *FUZZ_PARAM(unsigned int);

// Allocate the comparator and expose it to the pool.
guetzli::Comparator* comparator = new FuzzComparator(w, h, seed);

// Initialize fuzzer-visible attributes for state tracking used by other stubs.
FUZZ_SET_ATTR_INT(comparator, "block_phase", 0); // not in block-comparison phase initially
FUZZ_SET_ATTR_INT(comparator, "width", w);
FUZZ_SET_ATTR_INT(comparator, "height", h);
// Validation: comparator is a valid concrete instance, no FUZZ_PARAM usage inside methods (avoids prior compile errors),
// and attributes are set to support sequencing of Start/Finish/Switch calls.

