import random
import struct
from typing import List, Tuple

# Generator for raw interleaved 8-bit RGB buffers suitable for guetzli::EncodeRGBToJpeg
# The fuzzer stub derives width and height from the buffer size and two unsigned ints
# it samples. We only control the initial FUZZ_PARAM_STR buffer here, so we focus on
# producing RGB pixel data that is likely to compress well and exercise different
# encoder paths, while keeping size manageable (<4096 bytes).

MAX_TOTAL_BYTES = 4096

# Predefined interesting patterns to exercise encoder features
def solid_color(w: int, h: int, rgb: Tuple[int, int, int]) -> bytes:
    return bytes(list(rgb) * (w * h))

def checkerboard(w: int, h: int, c0: Tuple[int, int, int], c1: Tuple[int, int, int], block: int = 8) -> bytes:
    out = bytearray()
    for y in range(h):
        for x in range(w):
            use_c0 = ((x // block) + (y // block)) % 2 == 0
            out.extend(c0 if use_c0 else c1)
    return bytes(out)

def horizontal_gradient(w: int, h: int, c0: Tuple[int, int, int], c1: Tuple[int, int, int]) -> bytes:
    out = bytearray()
    for y in range(h):
        for x in range(w):
            t = x / max(1, w - 1)
            r = int(c0[0] * (1 - t) + c1[0] * t)
            g = int(c0[1] * (1 - t) + c1[1] * t)
            b = int(c0[2] * (1 - t) + c1[2] * t)
            out.extend((r, g, b))
    return bytes(out)

def vertical_gradient(w: int, h: int, c0: Tuple[int, int, int], c1: Tuple[int, int, int]) -> bytes:
    out = bytearray()
    for y in range(h):
        t = y / max(1, h - 1)
        r = int(c0[0] * (1 - t) + c1[0] * t)
        g = int(c0[1] * (1 - t) + c1[1] * t)
        b = int(c0[2] * (1 - t) + c1[2] * t)
        for x in range(w):
            out.extend((r, g, b))
    return bytes(out)

def stripes(w: int, h: int, horizontal: bool, period: int, c0: Tuple[int, int, int], c1: Tuple[int, int, int]) -> bytes:
    out = bytearray()
    for y in range(h):
        for x in range(w):
            idx = (y if horizontal else x) // max(1, period)
            out.extend(c0 if (idx % 2 == 0) else c1)
    return bytes(out)

def random_blocks(w: int, h: int, rng: random.Random, block: int = 8, palette: List[Tuple[int, int, int]] = None) -> bytes:
    if palette is None:
        palette = [(0,0,0),(255,255,255),(255,0,0),(0,255,0),(0,0,255),(255,255,0),(0,255,255),(255,0,255)]
    out = bytearray(w*h*3)
    for by in range(0, h, block):
        for bx in range(0, w, block):
            c = rng.choice(palette)
            for y in range(by, min(by+block, h)):
                for x in range(bx, min(bx+block, w)):
                    i = (y*w + x)*3
                    out[i:i+3] = bytes(c)
    return bytes(out)

# Choose dimensions that keep w*h*3 <= MAX_TOTAL_BYTES and that often align with 8x8 blocks.
# The stub will pick w and h based on its own randoms, but providing a buffer sized for common
# small images increases chance of valid configurations across different width/height picks.

def choose_dims(rng: random.Random) -> Tuple[int, int]:
    # Prefer multiples of 8, but add some variety.
    candidates = [(8,8),(16,16),(32,16),(16,24),(24,24),(32,24),(32,32),(40,24),(48,24),(64,16)]
    # Ensure size constraint
    candidates = [(w,h) for (w,h) in candidates if w*h*3 <= MAX_TOTAL_BYTES]
    if not candidates:
        # Fallback small
        return (8,8)
    # Weighted to smaller sizes to allow the stub to vary h effectively
    weights = [1.0/(w*h) for (w,h) in candidates]
    total = sum(weights)
    r = rng.random()*total
    acc=0.0
    for (w,h),wt in zip(candidates,weights):
        acc+=wt
        if r<=acc:
            return (w,h)
    return candidates[-1]

# Compose patterns for more diversity

def build_rgb_buffer(rng: random.Random, w: int, h: int) -> bytes:
    choice = rng.randint(0, 8)
    if choice == 0:
        # Solid color (including grayscale extremes)
        colors = [(0,0,0),(255,255,255),(128,128,128),(255,0,0),(0,255,0),(0,0,255)]
        return solid_color(w, h, rng.choice(colors))
    elif choice == 1:
        # Checkerboard with 8x8 or 16x16 blocks
        blk = rng.choice([4,8,16])
        return checkerboard(w, h, rng.choice([(0,0,0),(16,16,16),(32,32,32)]), rng.choice([(255,255,255),(224,224,224),(192,192,192)]), blk)
    elif choice == 2:
        # Horizontal gradient between random colors
        c0 = tuple(rng.randrange(0,256) for _ in range(3))
        c1 = tuple(rng.randrange(0,256) for _ in range(3))
        return horizontal_gradient(w, h, c0, c1)
    elif choice == 3:
        # Vertical gradient grayscale or color
        if rng.random()<0.5:
            g0 = rng.randrange(0,256); g1 = rng.randrange(0,256)
            return vertical_gradient(w, h, (g0,g0,g0), (g1,g1,g1))
        else:
            c0 = tuple(rng.randrange(0,256) for _ in range(3))
            c1 = tuple(rng.randrange(0,256) for _ in range(3))
            return vertical_gradient(w, h, c0, c1)
    elif choice == 4:
        # Stripes (horizontal or vertical)
        horizontal = rng.random()<0.5
        period = rng.choice([2,4,8,16])
        c0 = tuple(rng.randrange(0,256) for _ in range(3))
        c1 = tuple(rng.randrange(0,256) for _ in range(3))
        return stripes(w, h, horizontal, period, c0, c1)
    elif choice == 5:
        # Random 8x8 blocks from small palette
        return random_blocks(w, h, rng, block=rng.choice([4,8,16]))
    elif choice == 6:
        # Y-only variation (constant chroma), useful for subsampling paths
        y0 = rng.randrange(0,256); y1 = rng.randrange(0,256)
        def y_to_rgb(y):
            return (y, y, y)
        return horizontal_gradient(w, h, y_to_rgb(y0), y_to_rgb(y1))
    elif choice == 7:
        # Two-region split (left/right or top/bottom)
        split_vert = rng.random()<0.5
        c0 = tuple(rng.randrange(0,256) for _ in range(3))
        c1 = tuple(rng.randrange(0,256) for _ in range(3))
        out = bytearray()
        if split_vert:
            sx = rng.randrange(1, max(2, w))
            for y in range(h):
                for x in range(w):
                    out.extend(c0 if x < sx else c1)
        else:
            sy = rng.randrange(1, max(2, h))
            for y in range(h):
                for x in range(w):
                    out.extend(c0 if y < sy else c1)
        return bytes(out)
    else:
        # Mixed: checkerboard over gradient for richer frequency content
        base = horizontal_gradient(w, h, (0,0,0), (255,255,255))
        overlay = checkerboard(w, h, (0,0,0), (64,64,64), block=rng.choice([4,8,16]))
        out = bytearray(len(base))
        for i in range(0, len(base), 3):
            out[i] = min(255, base[i] + overlay[i])
            out[i+1] = min(255, base[i+1] + overlay[i+1])
            out[i+2] = min(255, base[i+2] + overlay[i+2])
        return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose dimensions and build an RGB buffer
    w, h = choose_dims(rng)
    buf = build_rgb_buffer(rng, w, h)
    # Ensure size bound
    if len(buf) > MAX_TOTAL_BYTES:
        buf = buf[:MAX_TOTAL_BYTES]
    return buf
